const gameHtml = "<!DOCTYPE html>\r\n\r\n<html lang=\"es\"><head>\r\n<meta charset=\"utf-8\"/>\r\n<meta content=\"width=device-width, initial-scale=1.0\" name=\"viewport\"/>\r\n<title>Aventura científica: Descubre los objetos</title>\r\n<!-- Tailwind CSS v3 -->\r\n<script src=\"https://cdn.tailwindcss.com?plugins=forms,container-queries\"></script>\r\n<!-- Google Fonts -->\r\n<link href=\"https://fonts.googleapis.com\" rel=\"preconnect\"/>\r\n<link crossorigin=\"\" href=\"https://fonts.gstatic.com\" rel=\"preconnect\"/>\r\n<link href=\"https://fonts.googleapis.com/css2?family=Fredoka:wght@400;500;600;700&amp;family=Quicksand:wght@500;600;700&amp;display=swap\" rel=\"stylesheet\"/>\r\n<script data-purpose=\"tailwind-config\">\r\n    tailwind.config = {\r\n      theme: {\r\n        extend: {\r\n          fontFamily: {\r\n            fredoka: ['Fredoka', 'sans-serif'],\r\n            quicksand: ['Quicksand', 'sans-serif'],\r\n          }\r\n        }\r\n      }\r\n    }\r\n  </script>\r\n<style>\r\n    @keyframes wiggle {\r\n      0%, 100% { transform: translateX(0); }\r\n      20% { transform: translateX(-8px) rotate(-2deg); }\r\n      40% { transform: translateX(8px) rotate(2deg); }\r\n      60% { transform: translateX(-5px) rotate(-1deg); }\r\n      80% { transform: translateX(5px) rotate(1deg); }\r\n    }\r\n    @keyframes bounce-gentle {\r\n      0%, 100% { transform: translateY(0); }\r\n      50% { transform: translateY(-6px); }\r\n    }\r\n    @keyframes popIn {\r\n      0% { transform: scale(0.65) translateY(-15px); opacity: 0; }\r\n      65% { transform: scale(1.1) translateY(2px); opacity: 1; }\r\n      100% { transform: scale(1) translateY(0); opacity: 1; }\r\n    }\r\n    @keyframes sparkleSpin {\r\n      0%, 100% { transform: rotate(0deg) scale(1); }\r\n      50% { transform: rotate(15deg) scale(1.15); }\r\n    }\r\n    @keyframes deskDragPulse {\r\n      0%, 100% { box-shadow: 0 0 35px 8px rgba(56, 189, 248, 0.7), inset 0 0 25px rgba(255, 255, 255, 0.6); }\r\n      50% { box-shadow: 0 0 50px 14px rgba(245, 158, 11, 0.8), inset 0 0 35px rgba(255, 255, 255, 0.9); }\r\n    }\r\n    @keyframes sparkleBurst {\r\n      0% {\r\n        transform: translate(-50%, -50%) translate(0, 0) scale(0) rotate(0deg);\r\n        opacity: 1;\r\n      }\r\n      70% {\r\n        opacity: 0.95;\r\n      }\r\n      100% {\r\n        transform: translate(-50%, -50%) translate(var(--tx, 40px), var(--ty, -40px)) scale(var(--scale, 1.25)) rotate(var(--rot, 180deg));\r\n        opacity: 0;\r\n      }\r\n    }\r\n    @keyframes haloPulseSoft {\r\n      0%, 100% {\r\n        box-shadow: 0 0 25px var(--glow-color, rgba(245, 158, 11, 0.5)), 0 8px 24px -4px rgba(0,0,0,0.18);\r\n      }\r\n      50% {\r\n        box-shadow: 0 0 45px var(--glow-bright, rgba(245, 158, 11, 0.85)), 0 12px 28px -4px rgba(0,0,0,0.22);\r\n      }\r\n    }\r\n\r\n    .animate-wiggle { animation: wiggle 0.5s ease-in-out; }\r\n    .animate-bounce-gentle { animation: bounce-gentle 1.6s infinite ease-in-out; }\r\n    .sparkle-icon { display: inline-block; animation: sparkleSpin 3s infinite ease-in-out; }\r\n\r\n    .placed-item-halo {\r\n      animation: popIn 0.38s cubic-bezier(0.34, 1.56, 0.64, 1) forwards, haloPulseSoft 2s infinite ease-in-out 0.4s;\r\n      border: 3.5px solid #ffffff;\r\n    }\r\n    .sparkle-particle {\r\n      position: absolute;\r\n      left: 50%;\r\n      top: 50%;\r\n      pointer-events: none;\r\n      z-index: 40;\r\n      animation: sparkleBurst 0.85s cubic-bezier(0.18, 0.89, 0.32, 1.25) forwards;\r\n      filter: drop-shadow(0 0 4px rgba(255,255,255,0.9));\r\n    }\r\n    .state-error-glow {\r\n      border-color: #ef4444 !important;\r\n      box-shadow: 0 0 40px rgba(239, 68, 68, 0.85) !important;\r\n      animation: wiggle 0.5s ease-in-out;\r\n    }\r\n    .state-success-glow {\r\n      border-color: #10b981 !important;\r\n      box-shadow: 0 0 45px rgba(16, 185, 129, 0.9) !important;\r\n    }\r\n    .desk-drag-active {\r\n      animation: deskDragPulse 1s infinite alternate !important;\r\n      border-color: #38bdf8 !important;\r\n    }\r\n    .desk-oval-shadow {\r\n      background: radial-gradient(ellipse at center, rgba(15, 23, 42, 0.45) 0%, transparent 72%);\r\n    }\r\n\r\n    .shelf-item-card {\r\n      transition: all 0.22s cubic-bezier(0.34, 1.56, 0.64, 1);\r\n    }\r\n    .shelf-item-card:hover {\r\n      transform: translateY(-8px) scale(1.08);\r\n      z-index: 20;\r\n    }\r\n    .shelf-item-card:active {\r\n      transform: scale(0.96);\r\n    }\r\n\r\n    .badge-kw {\r\n      display: inline-flex;\r\n      align-items: center;\r\n      gap: 0.3rem;\r\n      padding: 0.2rem 0.65rem;\r\n      border-radius: 9999px;\r\n      font-family: 'Fredoka', sans-serif;\r\n      font-weight: 700;\r\n      font-size: 0.85rem;\r\n      text-transform: uppercase;\r\n      box-shadow: 0 4px 10px rgba(0,0,0,0.12);\r\n    }\r\n  </style>\r\n</head>\r\n<body class=\"relative min-h-screen bg-gradient-to-br from-[#fef7ee] via-[#f0f9ff] to-[#ecfdf5] font-quicksand text-slate-800 flex flex-col justify-between select-none p-2 sm:p-4 md:p-6\" style=\"background: radial-gradient(circle at 10% 15%, rgba(254, 240, 138, 0.6) 0%, transparent 40%), radial-gradient(circle at 90% 12%, rgba(186, 230, 254, 0.6) 0%, transparent 42%), radial-gradient(circle at 85% 85%, rgba(254, 205, 211, 0.5) 0%, transparent 45%), linear-gradient(135deg, #fef9c3 0%, #e0f2fe 40%, #fce7f3 75%, #dcfce7 100%);\">\r\n<!-- Confetti Background Elements -->\r\n<div aria-hidden=\"true\" class=\"fixed inset-0 pointer-events-none overflow-hidden z-0\">\r\n<div class=\"absolute top-[8%] left-[4%] w-3 h-3 rounded-sm bg-rose-400 rotate-12 opacity-70\"></div>\r\n<div class=\"absolute top-[14%] right-[8%] w-4 h-2 rounded bg-amber-400 -rotate-45 opacity-75\"></div>\r\n<div class=\"absolute top-[30%] left-[6%] w-3.5 h-3 rounded-sm bg-sky-400 rotate-45 opacity-65\"></div>\r\n<div class=\"absolute top-[65%] right-[5%] w-4 h-2 bg-emerald-400 rotate-12 opacity-70\"></div>\r\n</div>\r\n<!-- Header -->\r\n<header class=\"relative z-10 w-full max-w-6xl mx-auto mb-3 sm:mb-4\">\r\n<div class=\"bg-white/90 backdrop-blur-md rounded-2xl sm:rounded-3xl p-3 sm:p-4 shadow-sm border border-white/80 flex items-center justify-between gap-2\">\r\n<!-- Back Button -->\r\n<div class=\"w-1/3 flex justify-start\">\r\n<button class=\"hidden items-center gap-1 px-3 py-1.5 sm:px-4 sm:py-2 rounded-xl bg-amber-100 hover:bg-amber-200 text-amber-900 font-fredoka font-bold text-xs sm:text-sm transition border border-amber-300 active:scale-95 shadow-sm\" id=\"btn-back\" onclick=\"changeLevel(currentLevel - 1)\">\r\n<span>◀</span>\r\n<span class=\"hidden sm:inline\">Nivel</span> anterior\r\n        </button>\r\n</div>\r\n<!-- Level Indicators -->\r\n<div class=\"w-full sm:w-auto flex flex-col items-center justify-center text-center\">\r\n<div class=\"flex items-center gap-1.5 sm:gap-2 mb-1\" id=\"level-dots-container\">\r\n<span class=\"w-3.5 h-3.5 rounded-full bg-amber-400 ring-2 ring-amber-200 animate-pulse\"></span>\r\n<span class=\"w-3 h-3 rounded-full bg-slate-200 border border-slate-300\"></span>\r\n<span class=\"w-3 h-3 rounded-full bg-slate-200 border border-slate-300\"></span>\r\n<span class=\"w-3 h-3 rounded-full bg-slate-200 border border-slate-300\"></span>\r\n<span class=\"w-3 h-3 rounded-full bg-slate-200 border border-slate-300\"></span>\r\n</div>\r\n<span class=\"font-fredoka font-bold text-sm sm:text-base text-slate-700 tracking-wide\" id=\"level-title-badge\">● ○ ○ ○ ○ Nivel 1/5</span>\r\n</div>\r\n<!-- Audio Button & School Badge -->\r\n<div class=\"w-1/3 flex justify-end items-center gap-2\">\r\n<button class=\"flex items-center gap-1.5 px-3 py-1.5 rounded-full font-fredoka font-bold text-xs sm:text-sm tracking-wide transition-all shadow-sm active:scale-95 border bg-emerald-100 text-emerald-800 border-emerald-300 hover:bg-emerald-200\" id=\"btn-toggle-sound\" onclick=\"toggleAudioMute()\" title=\"Activar / Desactivar Sonido\">\r\n<span class=\"text-sm sm:text-base\" id=\"sound-btn-icon\">🔊</span>\r\n<span class=\"hidden sm:inline\" id=\"sound-btn-text\">Sonido: ACTIVADO</span>\r\n</button>\r\n<div class=\"hidden md:flex text-xs font-fredoka text-slate-500 font-medium items-center gap-1.5 px-3 py-1 rounded-full bg-slate-100/90 border border-slate-200\">\r\n<span>🧪</span> Laboratorio\r\n        </div>\r\n</div>\r\n</div>\r\n</header>\r\n<!-- Main Game Board -->\r\n<main class=\"relative z-10 w-full max-w-6xl mx-auto flex-1 grid grid-cols-1 lg:grid-cols-12 gap-4 items-stretch\">\r\n<!-- Left Column: Teacher Character & Speech Bubble -->\r\n<section class=\"lg:col-span-5 flex flex-col justify-between gap-3\">\r\n<!-- Bubble -->\r\n<div class=\"relative bg-white rounded-2xl sm:rounded-3xl p-4 sm:p-5 shadow-md border-2 border-sky-100 min-h-[90px] sm:min-h-[120px] flex items-center justify-center cursor-default\" id=\"dialogue-box\">\r\n<div class=\"text-slate-700 text-sm sm:text-base md:text-lg font-medium leading-relaxed text-center\" id=\"dialogue-text\">\r\n          ¡Hola, explorador! <span class=\"sparkle-icon\">🔍</span> ¿Puedes ayudarme a encontrar algo que sea... <span class=\"badge-kw bg-emerald-500 text-white\">¡GRANDE! 📦</span> y <span class=\"badge-kw bg-emerald-600 text-white\">¡VERDE! 🌿</span> <span class=\"sparkle-icon\">✨</span>?\r\n        </div>\r\n<!-- Arrow -->\r\n<div class=\"absolute -bottom-3 left-1/2 -translate-x-1/2 w-0 h-0 border-l-[12px] border-l-transparent border-r-[12px] border-r-transparent border-t-[14px] border-t-white\"></div>\r\n</div>\r\n<!-- Teacher Character Card -->\r\n<div class=\"relative flex-1 bg-white rounded-2xl sm:rounded-3xl p-2 border border-slate-200 flex flex-col items-center justify-center overflow-hidden min-h-[220px] shadow-sm\">\r\n<img alt=\"Profesor Leo\" class=\"w-full h-full object-cover object-center max-h-[340px] rounded-xl\" src=\"/images/semana1/cientifico.jpg\"/>\r\n<div class=\"absolute bottom-3 bg-white/95 backdrop-blur-md px-4 py-1 rounded-full shadow border border-slate-200 text-slate-800 font-fredoka font-bold text-xs sm:text-sm tracking-wide flex items-center gap-2\">\r\n<span class=\"w-2.5 h-2.5 rounded-full bg-emerald-500 animate-pulse\"></span> Prof. Leo\r\n        </div>\r\n</div>\r\n</section>\r\n<!-- Right Column: Desk & Shelf -->\r\n<section class=\"lg:col-span-7 flex flex-col justify-between gap-3\">\r\n<!-- Zone 1: Delivery Desk -->\r\n<div class=\"relative rounded-2xl sm:rounded-3xl overflow-hidden shadow-md border-2 border-slate-200 aspect-[16/9] min-h-[210px] flex flex-col items-center justify-center bg-cover bg-center transition-all\" id=\"drop-desk-container\" ondragleave=\"handleDragLeave(event)\" ondragover=\"handleDragOver(event)\" ondrop=\"handleDrop(event)\" style=\"background-image: url('/images/semana1/escritorio.jpg');\"><style>\r\n  @keyframes victoriaGlow {\r\n    0%, 100% {\r\n      box-shadow: 0 0 35px rgba(16, 185, 129, 0.95), 0 0 75px rgba(52, 211, 153, 0.8), inset 0 0 32px rgba(16, 185, 129, 0.55);\r\n      border-color: #10b981 !important;\r\n    }\r\n    50% {\r\n      box-shadow: 0 0 55px rgba(16, 185, 129, 1), 0 0 110px rgba(52, 211, 153, 0.95), inset 0 0 48px rgba(16, 185, 129, 0.75);\r\n      border-color: #34d399 !important;\r\n    }\r\n  }\r\n  @keyframes errorFlashShake {\r\n    0% { transform: translateX(0); box-shadow: 0 0 45px rgba(239, 68, 68, 0.95), 0 0 85px rgba(220, 38, 38, 0.85), inset 0 0 40px rgba(239, 68, 68, 0.55); }\r\n    15% { transform: translateX(-12px) rotate(-1.5deg); }\r\n    30% { transform: translateX(12px) rotate(1.5deg); box-shadow: 0 0 65px rgba(239, 68, 68, 1), 0 0 120px rgba(220, 38, 38, 0.95), inset 0 0 50px rgba(239, 68, 68, 0.75); }\r\n    45% { transform: translateX(-8px) rotate(-1deg); }\r\n    60% { transform: translateX(8px) rotate(1deg); }\r\n    75% { transform: translateX(-4px); }\r\n    90% { transform: translateX(4px); }\r\n    100% { transform: translateX(0); box-shadow: 0 0 40px rgba(239, 68, 68, 0.9), 0 0 80px rgba(220, 38, 38, 0.75), inset 0 0 35px rgba(239, 68, 68, 0.45); }\r\n  }\r\n  .state-success-glow {\r\n    border: 4px solid #10b981 !important;\r\n    animation: victoriaGlow 1.4s infinite ease-in-out !important;\r\n    position: relative;\r\n    z-index: 15;\r\n  }\r\n  .state-error-glow {\r\n    border: 4px solid #ef4444 !important;\r\n    animation: errorFlashShake 0.65s cubic-bezier(0.36, 0.07, 0.19, 0.97) both !important;\r\n    position: relative;\r\n    z-index: 15;\r\n  }\r\n</style>\r\n<!-- Tag -->\r\n<div class=\"absolute top-3 left-3 bg-white/90 backdrop-blur-sm px-3 py-1 rounded-full shadow text-sky-800 font-fredoka font-bold text-xs tracking-wider flex items-center gap-1.5 border border-sky-100 z-10\">\r\n<span class=\"w-2 h-2 rounded-full bg-sky-500\"></span> PUPITRE\r\n        </div>\r\n<!-- Desk Slot / Target Zone -->\r\n<div class=\"relative z-10 flex flex-col items-center justify-center cursor-pointer\" id=\"desk-slot\" onclick=\"handleSlotClick()\">\r\n<!-- Empty State Target -->\r\n<div class=\"w-36 h-36 sm:w-44 sm:h-44 rounded-2xl border-2 border-dashed border-white/90 bg-white/40 backdrop-blur-xs flex flex-col items-center justify-center text-center p-3 transition-all\" id=\"slot-placeholder\">\r\n<span class=\"text-3xl mb-1\">📥</span>\r\n<span class=\"font-fredoka font-bold text-xs sm:text-sm text-slate-800 uppercase tracking-wider\" id=\"slot-placeholder-title\">COLOCA AQUÍ</span>\r\n<span class=\"text-[11px] text-slate-700 font-semibold mt-0.5\">Toca o arrastra un objeto</span>\r\n</div>\r\n<!-- Placed Item Container -->\r\n<div class=\"flex flex-col items-center justify-center relative hidden\" id=\"desk-placed-item\">\r\n<!-- Sparkle Particle Explosion Overlay -->\r\n<div class=\"absolute inset-0 pointer-events-none z-30 overflow-visible\" id=\"desk-sparkles-layer\"></div>\r\n<div class=\"w-28 h-28 sm:w-36 sm:h-36 rounded-2xl p-3 flex flex-col items-center justify-center relative placed-item-halo bg-[#fff7ed]\" id=\"placed-card-wrapper\"></div>\r\n<div class=\"w-28 sm:w-36 h-4 desk-oval-shadow mt-1\"></div>\r\n</div>\r\n</div>\r\n<!-- Return Item Button -->\r\n<div class=\"absolute bottom-3 z-20 hidden\" id=\"return-shelf-action\">\r\n<button class=\"bg-white hover:bg-orange-50 border-2 border-orange-400 text-orange-600 font-fredoka font-bold text-xs sm:text-sm px-5 py-1.5 rounded-full shadow-md active:scale-95 flex items-center gap-2 transition\" onclick=\"returnItemToShelf()\">\r\n<span>⤹</span> Regresar objeto al estante\r\n          </button>\r\n</div>\r\n</div>\r\n<!-- Zone 2: Wooden Shelf with 4 Objects -->\r\n<div class=\"relative pt-2 pb-2\">\r\n<div class=\"grid grid-cols-4 gap-2 sm:gap-3 px-2 sm:px-4 z-10 relative\" id=\"items-grid\"></div>\r\n<!-- Shelf Plank -->\r\n<div class=\"relative w-full mt-2\">\r\n<div class=\"h-1.5 w-full bg-amber-400 rounded-t-sm opacity-90\"></div>\r\n<div class=\"h-6 sm:h-7 w-full bg-gradient-to-r from-amber-800 via-amber-700 to-amber-900 rounded-sm shadow-md border-b-2 border-amber-950 flex items-center px-4 justify-between\">\r\n<div class=\"w-10 h-1 bg-amber-600/50 rounded\"></div>\r\n<div class=\"w-16 h-1 bg-amber-600/30 rounded\"></div>\r\n<div class=\"w-12 h-1 bg-amber-600/50 rounded\"></div>\r\n</div>\r\n<div class=\"flex justify-between px-8 sm:px-14\">\r\n<div class=\"w-6 h-6 bg-amber-900 rounded-b shadow-sm border-r border-amber-950\"></div>\r\n<div class=\"w-6 h-6 bg-amber-900 rounded-b shadow-sm border-l border-amber-950\"></div>\r\n</div>\r\n</div>\r\n</div>\r\n</section>\r\n</main>\r\n<!-- Bottom Action Bar -->\r\n<footer class=\"sticky bottom-0 z-30 w-full max-w-6xl mx-auto mt-2 pt-1 pb-1\">\r\n<div class=\"bg-white/95 backdrop-blur-md rounded-2xl sm:rounded-3xl p-3 shadow-lg border border-white/80\">\r\n<div class=\"grid grid-cols-2 gap-3 items-stretch\" id=\"actions-button-grid\">\r\n<!-- Reiniciar -->\r\n<button class=\"flex items-center justify-center gap-2 px-4 py-2.5 rounded-2xl font-fredoka font-bold text-xs sm:text-base tracking-wide bg-slate-100 hover:bg-slate-200 text-slate-700 border border-slate-300 transition active:scale-95 shadow-sm\" id=\"btn-reiniciar-nivel\" onclick=\"resetCurrentLevelState()\">\r\n<span>🔄</span> Reiniciar\r\n        </button>\r\n<!-- Comprobar -->\r\n<button class=\"flex items-center justify-center gap-2 px-4 py-2.5 rounded-2xl font-fredoka font-bold text-xs sm:text-base tracking-wide bg-emerald-600 hover:bg-emerald-500 text-white transition active:scale-95 shadow-md shadow-emerald-500/20\" id=\"btn-check\" onclick=\"checkCurrentAnswer()\">\r\n<span>✔</span> Comprobar\r\n        </button>\r\n<!-- Volver a jugar (Endgame) -->\r\n<button class=\"hidden items-center justify-center gap-2 px-4 py-2.5 rounded-2xl font-fredoka font-bold text-xs sm:text-base tracking-wide bg-purple-600 hover:bg-purple-500 text-white transition active:scale-95 shadow-md\" id=\"btn-replay\" onclick=\"replayLevelOrGame()\">\r\n<span>🎮</span> Volver a jugar\r\n        </button>\r\n<!-- Volver al inicio (Endgame) -->\r\n<button class=\"hidden items-center justify-center gap-2 px-4 py-2.5 rounded-2xl font-fredoka font-bold text-xs sm:text-base tracking-wide bg-amber-500 hover:bg-amber-400 text-white transition active:scale-95 shadow-md animate-bounce-gentle\" id=\"btn-home\" onclick=\"restartGameEntirely()\">\r\n<span>🏠</span> Volver al inicio\r\n        </button>\r\n</div>\r\n<!-- Status Pill & Next Level Button -->\r\n<div class=\"mt-2.5 pt-2 border-t border-slate-100 flex flex-wrap items-center justify-between gap-2\">\r\n<div class=\"flex items-center gap-2 text-xs font-fredoka text-slate-500 bg-slate-50 px-3 py-1 rounded-full border border-slate-200\" id=\"status-pill\">\r\n<span>💡</span>\r\n<span id=\"status-pill-text\">Selecciona un elemento para colocarlo en el pupitre y pulsa comprobar</span>\r\n</div>\r\n<div class=\"ml-auto\">\r\n<button class=\"hidden items-center gap-2 text-white font-fredoka font-bold text-xs sm:text-sm px-6 py-2 rounded-2xl tracking-wider bg-amber-500 hover:bg-amber-400 shadow-md active:scale-95 animate-bounce-gentle\" id=\"btn-next\" onclick=\"goToNextLevel()\">\r\n<span>¡Siguiente nivel!</span> ➔\r\n          </button>\r\n</div>\r\n</div>\r\n</div>\r\n</footer>\r\n<script data-purpose=\"audio-engine-and-game\">\r\n    /* =========================================================\r\n       1. WEB AUDIO API ENGINE (Clean, robust, no browser lock)\r\n       ========================================================= */\r\n    let audioCtx = null;\r\n    let isSoundMuted = false;\r\n\r\n    function getAudio() {\r\n      if (!audioCtx) {\r\n        audioCtx = new (window.AudioContext || window.webkitAudioContext)();\r\n      }\r\n      if (audioCtx.state === 'suspended') {\r\n        audioCtx.resume();\r\n      }\r\n      return audioCtx;\r\n    }\r\n\r\n    // Unlock audio context on any first user interaction anywhere\r\n    const unlockAudio = () => {\r\n      getAudio();\r\n      window.removeEventListener('pointerdown', unlockAudio);\r\n      window.removeEventListener('click', unlockAudio);\r\n      window.removeEventListener('touchstart', unlockAudio);\r\n      window.removeEventListener('keydown', unlockAudio);\r\n    };\r\n    window.addEventListener('pointerdown', unlockAudio);\r\n    window.addEventListener('click', unlockAudio);\r\n    window.addEventListener('touchstart', unlockAudio);\r\n    window.addEventListener('keydown', unlockAudio);\r\n\r\n    // Audio SFX Functions\r\n    function playPop() {\r\n      if (isSoundMuted) return;\r\n      const ctx = getAudio();\r\n      const osc = ctx.createOscillator();\r\n      const gain = ctx.createGain();\r\n      const now = ctx.currentTime;\r\n\r\n      osc.type = 'sine';\r\n      osc.frequency.setValueAtTime(250, now);\r\n      osc.frequency.exponentialRampToValueAtTime(600, now + 0.12);\r\n\r\n      gain.gain.setValueAtTime(0.4, now);\r\n      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.12);\r\n\r\n      osc.connect(gain);\r\n      gain.connect(ctx.destination);\r\n      osc.start(now);\r\n      osc.stop(now + 0.12);\r\n    }\r\n\r\n    function playWhoosh() {\r\n      if (isSoundMuted) return;\r\n      const ctx = getAudio();\r\n      const osc = ctx.createOscillator();\r\n      const gain = ctx.createGain();\r\n      const now = ctx.currentTime;\r\n\r\n      osc.type = 'sine';\r\n      osc.frequency.setValueAtTime(450, now);\r\n      osc.frequency.exponentialRampToValueAtTime(180, now + 0.14);\r\n\r\n      gain.gain.setValueAtTime(0.35, now);\r\n      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.14);\r\n\r\n      osc.connect(gain);\r\n      gain.connect(ctx.destination);\r\n      osc.start(now);\r\n      osc.stop(now + 0.14);\r\n    }\r\n\r\n    function playSuccess() {\r\n      if (isSoundMuted) return;\r\n      const ctx = getAudio();\r\n      const notes = [523.25, 659.25, 783.99, 1046.5]; // C5, E5, G5, C6\r\n      const start = ctx.currentTime;\r\n\r\n      notes.forEach((freq, idx) => {\r\n        const osc = ctx.createOscillator();\r\n        const gain = ctx.createGain();\r\n        const t = start + idx * 0.08;\r\n\r\n        osc.type = 'triangle';\r\n        osc.frequency.setValueAtTime(freq, t);\r\n\r\n        gain.gain.setValueAtTime(0.38, t);\r\n        gain.gain.exponentialRampToValueAtTime(0.001, t + 0.18);\r\n\r\n        osc.connect(gain);\r\n        gain.connect(ctx.destination);\r\n        osc.start(t);\r\n        osc.stop(t + 0.18);\r\n      });\r\n    }\r\n\r\n    function playError() {\r\n      if (isSoundMuted) return;\r\n      const ctx = getAudio();\r\n      const now = ctx.currentTime;\r\n\r\n      const osc1 = ctx.createOscillator();\r\n      const gain1 = ctx.createGain();\r\n      osc1.type = 'sawtooth';\r\n      osc1.frequency.setValueAtTime(280, now);\r\n      osc1.frequency.exponentialRampToValueAtTime(180, now + 0.15);\r\n      gain1.gain.setValueAtTime(0.3, now);\r\n      gain1.gain.exponentialRampToValueAtTime(0.001, now + 0.15);\r\n      osc1.connect(gain1);\r\n      gain1.connect(ctx.destination);\r\n      osc1.start(now);\r\n      osc1.stop(now + 0.15);\r\n\r\n      const osc2 = ctx.createOscillator();\r\n      const gain2 = ctx.createGain();\r\n      osc2.type = 'sawtooth';\r\n      osc2.frequency.setValueAtTime(220, now + 0.16);\r\n      osc2.frequency.exponentialRampToValueAtTime(140, now + 0.32);\r\n      gain2.gain.setValueAtTime(0.3, now + 0.16);\r\n      gain2.gain.exponentialRampToValueAtTime(0.001, now + 0.32);\r\n      osc2.connect(gain2);\r\n      gain2.connect(ctx.destination);\r\n      osc2.start(now + 0.16);\r\n      osc2.stop(now + 0.32);\r\n    }\r\n\r\n    function playClick() {\r\n      if (isSoundMuted) return;\r\n      const ctx = getAudio();\r\n      const osc = ctx.createOscillator();\r\n      const gain = ctx.createGain();\r\n      const now = ctx.currentTime;\r\n\r\n      osc.type = 'sine';\r\n      osc.frequency.setValueAtTime(700, now);\r\n      osc.frequency.exponentialRampToValueAtTime(350, now + 0.05);\r\n\r\n      gain.gain.setValueAtTime(0.25, now);\r\n      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.05);\r\n\r\n      osc.connect(gain);\r\n      gain.connect(ctx.destination);\r\n      osc.start(now);\r\n      osc.stop(now + 0.05);\r\n    }\r\n\r\n    function playDing() {\r\n      if (isSoundMuted) return;\r\n      const ctx = getAudio();\r\n      const osc = ctx.createOscillator();\r\n      const gain = ctx.createGain();\r\n      const now = ctx.currentTime;\r\n\r\n      osc.type = 'sine';\r\n      osc.frequency.setValueAtTime(1046.5, now); // C6 bell\r\n\r\n      gain.gain.setValueAtTime(0.4, now);\r\n      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.35);\r\n\r\n      osc.connect(gain);\r\n      gain.connect(ctx.destination);\r\n      osc.start(now);\r\n      osc.stop(now + 0.35);\r\n    }\r\n\r\n    function playWin() {\r\n      if (isSoundMuted) return;\r\n      const ctx = getAudio();\r\n      const chords = [\r\n        { f: [523.25, 659.25], t: 0 },\r\n        { f: [587.33, 739.99], t: 0.14 },\r\n        { f: [659.25, 830.61], t: 0.28 },\r\n        { f: [783.99, 1046.50], t: 0.44 }\r\n      ];\r\n      const start = ctx.currentTime;\r\n\r\n      chords.forEach(chord => {\r\n        chord.f.forEach(freq => {\r\n          const osc = ctx.createOscillator();\r\n          const gain = ctx.createGain();\r\n          const t = start + chord.t;\r\n\r\n          osc.type = 'triangle';\r\n          osc.frequency.setValueAtTime(freq, t);\r\n\r\n          gain.gain.setValueAtTime(0.28, t);\r\n          gain.gain.exponentialRampToValueAtTime(0.001, t + 0.3);\r\n\r\n          osc.connect(gain);\r\n          gain.connect(ctx.destination);\r\n          osc.start(t);\r\n          osc.stop(t + 0.3);\r\n        });\r\n      });\r\n    }\r\n\r\n    function toggleAudioMute() {\r\n      getAudio();\r\n      isSoundMuted = !isSoundMuted;\r\n      const btn = document.getElementById('btn-toggle-sound');\r\n      const icon = document.getElementById('sound-btn-icon');\r\n      const text = document.getElementById('sound-btn-text');\r\n\r\n      if (isSoundMuted) {\r\n        btn.className = \"flex items-center gap-1.5 px-3 py-1.5 rounded-full font-fredoka font-bold text-xs sm:text-sm tracking-wide transition-all shadow-sm active:scale-95 border bg-rose-100 text-rose-800 border-rose-300 hover:bg-rose-200\";\r\n        icon.textContent = \"🔇\";\r\n        text.textContent = \"Sonido: SILENCIADO\";\r\n      } else {\r\n        btn.className = \"flex items-center gap-1.5 px-3 py-1.5 rounded-full font-fredoka font-bold text-xs sm:text-sm tracking-wide transition-all shadow-sm active:scale-95 border bg-emerald-100 text-emerald-800 border-emerald-300 hover:bg-emerald-200\";\r\n        icon.textContent = \"🔊\";\r\n        text.textContent = \"Sonido: ACTIVADO\";\r\n        playDing();\r\n      }\r\n    }\r\n\r\n    /* =========================================================\r\n       2. GAME DATA AND STATE\r\n       ========================================================= */\r\n    const GAME_LEVELS = [\r\n      {\r\n        id: 1,\r\n        title: \"● ○ ○ ○ ○ Nivel 1/5\",\r\n        bubble: `¡Hola, explorador! <span class=\"sparkle-icon\">🔍</span> ¿Puedes ayudarme a encontrar algo que sea... <span class=\"badge-kw bg-emerald-500 text-white\">¡GRANDE! 📦</span> y <span class=\"badge-kw bg-emerald-600 text-white\">¡VERDE! 🌿</span> <span class=\"sparkle-icon\">✨</span>?`,\r\n        correctKey: \"cuaderno\",\r\n        correctMsg: \"¡Excelente trabajo, pequeño científico! ¡El cuaderno es grande y verde! 🎉\"\r\n      },\r\n      {\r\n        id: 2,\r\n        title: \"● ● ○ ○ ○ Nivel 2/5\",\r\n        bubble: `¡Bienvenido al Nivel 2! <span class=\"sparkle-icon\">🚀</span> ¿Puedes ayudarme a encontrar algo que sea... <span class=\"badge-kw bg-amber-400 text-amber-950\">¡PEQUEÑO! ✨</span> y <span class=\"badge-kw bg-sky-500 text-white\">¡AZUL! 🟦🧼</span>?`,\r\n        correctKey: \"borrador\",\r\n        correctMsg: \"¡Fantástico! ¡El borrador azul es pequeño y perfecto para nuestras notas! 🎉\"\r\n      },\r\n      {\r\n        id: 3,\r\n        title: \"● ● ● ○ ○ Nivel 3/5\",\r\n        bubble: `¡Nivel 3 activado! <span class=\"sparkle-icon\">🌟</span> ¿Puedes ayudarme a encontrar algo que sea... <span class=\"badge-kw bg-orange-500 text-white\">¡LARGO! 📐</span> y <span class=\"badge-kw bg-amber-800 text-white\">¡DE MADERA! 🪵</span>?`,\r\n        correctKey: \"regla\",\r\n        correctMsg: \"¡Muy bien! ¡La regla de madera es larga, precisa e ideal para medir trazos rectos! 🎉\"\r\n      },\r\n      {\r\n        id: 4,\r\n        title: \"● ● ● ● ○ Nivel 4/5\",\r\n        bubble: `¡Nivel 4 de laboratorio! <span class=\"sparkle-icon\">🔬</span> Necesito algo que sea... <span class=\"badge-kw bg-cyan-600 text-white\">¡TRANSPARENTE! 🔍</span> y tenga <span class=\"badge-kw bg-fuchsia-600 text-white\">¡AUMENTO / CRISTAL! ✨</span>`,\r\n        correctKey: \"lupa\",\r\n        correctMsg: \"¡Genial observación! ¡La lupa de explorador tiene cristal transparente y aumento! 🎉\"\r\n      },\r\n      {\r\n        id: 5,\r\n        title: \"● ● ● ● ● ¡Desafío Final 5/5! 🏆\",\r\n        bubble: `¡Misión final, explorador! <span class=\"sparkle-icon\">✨</span> Para graduarte necesito algo que sea... <span class=\"badge-kw bg-blue-700 text-white\">¡REDONDO! 🌐</span> y sirva <span class=\"badge-kw bg-amber-400 text-amber-950\">¡PARA VIAJAR POR EL MUNDO! 🌍🏆</span>`,\r\n        correctKey: \"globo\",\r\n        correctMsg: \"¡VICTORIA TOTAL! 🏆 ¡Has completado los 5 niveles del laboratorio con honores!\"\r\n      }\r\n    ];\r\n\r\n    const ITEMS_DB = {\r\n      // Set 1 (Niveles 1, 2, 3)\r\n      lapiz: {\r\n        id: \"lapiz\", name: \"Lápiz\", bg: \"bg-[#fff7ed]\", border: \"border-orange-300\",\r\n        sparkleColors: [\"#fbbf24\", \"#f59e0b\", \"#fde047\", \"#ffffff\"],\r\n        glowColor: \"rgba(245, 158, 11, 0.5)\",\r\n        glowBright: \"rgba(251, 191, 36, 0.9)\",\r\n        svg: `<svg viewBox=\"0 0 64 64\" class=\"w-12 h-12 sm:w-16 sm:h-16\" fill=\"none\">\r\n          <path d=\"M44 8L56 20L22 54L10 54L10 42L44 8Z\" fill=\"#F59E0B\" stroke=\"#78350F\" stroke-width=\"2.5\" stroke-linejoin=\"round\"/>\r\n          <path d=\"M10 42L22 54L10 54Z\" fill=\"#FCD34D\"/>\r\n          <path d=\"M10 54L14 50L10 46V54Z\" fill=\"#1F2937\"/>\r\n          <path d=\"M38 14L50 26\" stroke=\"#D97706\" stroke-width=\"2\"/>\r\n          <path d=\"M48 4L59 15\" stroke=\"#F43F5E\" stroke-width=\"4\" stroke-linecap=\"round\"/>\r\n        </svg>`\r\n      },\r\n      borrador: {\r\n        id: \"borrador\", name: \"Borrador\", bg: \"bg-[#e0f2fe]\", border: \"border-sky-300\",\r\n        sparkleColors: [\"#38bdf8\", \"#0284c7\", \"#f43f5e\", \"#ffffff\"],\r\n        glowColor: \"rgba(56, 189, 248, 0.5)\",\r\n        glowBright: \"rgba(14, 165, 233, 0.9)\",\r\n        svg: `<svg viewBox=\"0 0 64 64\" class=\"w-12 h-12 sm:w-16 sm:h-16\" fill=\"none\">\r\n          <rect x=\"10\" y=\"22\" width=\"22\" height=\"24\" rx=\"4\" transform=\"rotate(-15 21 34)\" fill=\"#0284C7\" stroke=\"#0369A1\" stroke-width=\"2.5\"/>\r\n          <rect x=\"28\" y=\"17\" width=\"24\" height=\"24\" rx=\"4\" transform=\"rotate(-15 40 29)\" fill=\"#EF4444\" stroke=\"#B91C1C\" stroke-width=\"2.5\"/>\r\n          <line x1=\"28\" y1=\"18\" x2=\"22\" y2=\"40\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\r\n        </svg>`\r\n      },\r\n      cuaderno: {\r\n        id: \"cuaderno\", name: \"Cuaderno\", bg: \"bg-[#e6fbf3]\", border: \"border-emerald-300\",\r\n        sparkleColors: [\"#34d399\", \"#10b981\", \"#6ee7b7\", \"#ffffff\"],\r\n        glowColor: \"rgba(16, 185, 129, 0.5)\",\r\n        glowBright: \"rgba(52, 211, 153, 0.9)\",\r\n        svg: `<svg viewBox=\"0 0 64 64\" class=\"w-12 h-12 sm:w-16 sm:h-16\" fill=\"none\">\r\n          <rect x=\"14\" y=\"10\" width=\"38\" height=\"46\" rx=\"4\" fill=\"#10B981\" stroke=\"#047857\" stroke-width=\"2.5\"/>\r\n          <rect x=\"24\" y=\"16\" width=\"20\" height=\"14\" rx=\"2\" fill=\"#FFFFFF\" opacity=\"0.9\"/>\r\n          <line x1=\"14\" y1=\"18\" x2=\"20\" y2=\"18\" stroke=\"#047857\" stroke-width=\"2.5\"/>\r\n          <line x1=\"14\" y1=\"26\" x2=\"20\" y2=\"26\" stroke=\"#047857\" stroke-width=\"2.5\"/>\r\n          <line x1=\"14\" y1=\"34\" x2=\"20\" y2=\"34\" stroke=\"#047857\" stroke-width=\"2.5\"/>\r\n          <line x1=\"14\" y1=\"42\" x2=\"20\" y2=\"42\" stroke=\"#047857\" stroke-width=\"2.5\"/>\r\n        </svg>`\r\n      },\r\n      regla: {\r\n        id: \"regla\", name: \"Regla\", bg: \"bg-[#fef3c7]\", border: \"border-amber-300\",\r\n        sparkleColors: [\"#fb923c\", \"#f59e0b\", \"#fed7aa\", \"#ffffff\"],\r\n        glowColor: \"rgba(249, 115, 22, 0.5)\",\r\n        glowBright: \"rgba(251, 146, 60, 0.9)\",\r\n        svg: `<svg viewBox=\"0 0 64 64\" class=\"w-12 h-12 sm:w-16 sm:h-16\" fill=\"none\">\r\n          <rect x=\"10\" y=\"24\" width=\"44\" height=\"16\" rx=\"2.5\" fill=\"#D97706\" stroke=\"#92400E\" stroke-width=\"2\"/>\r\n          <line x1=\"16\" y1=\"24\" x2=\"16\" y2=\"32\" stroke=\"#451A03\" stroke-width=\"2\"/>\r\n          <line x1=\"24\" y1=\"24\" x2=\"24\" y2=\"30\" stroke=\"#451A03\" stroke-width=\"1.5\"/>\r\n          <line x1=\"32\" y1=\"24\" x2=\"32\" y2=\"32\" stroke=\"#451A03\" stroke-width=\"2\"/>\r\n          <line x1=\"40\" y1=\"24\" x2=\"40\" y2=\"30\" stroke=\"#451A03\" stroke-width=\"1.5\"/>\r\n          <line x1=\"48\" y1=\"24\" x2=\"48\" y2=\"32\" stroke=\"#451A03\" stroke-width=\"2\"/>\r\n        </svg>`\r\n      },\r\n\r\n      // Set 2 (Nivel 4)\r\n      tijeras: {\r\n        id: \"tijeras\", name: \"Tijeras\", bg: \"bg-[#ffe4e6]\", border: \"border-rose-300\",\r\n        sparkleColors: [\"#fb7185\", \"#f43f5e\", \"#fda4af\", \"#ffffff\"],\r\n        glowColor: \"rgba(244, 63, 94, 0.5)\",\r\n        glowBright: \"rgba(251, 113, 133, 0.9)\",\r\n        svg: `<svg viewBox=\"0 0 64 64\" class=\"w-12 h-12 sm:w-16 sm:h-16\" fill=\"none\">\r\n          <circle cx=\"20\" cy=\"46\" r=\"8\" stroke=\"#E11D48\" stroke-width=\"3\" fill=\"none\"/>\r\n          <circle cx=\"44\" cy=\"46\" r=\"8\" stroke=\"#E11D48\" stroke-width=\"3\" fill=\"none\"/>\r\n          <path d=\"M25 40L42 14\" stroke=\"#94A3B8\" stroke-width=\"3.5\" stroke-linecap=\"round\"/>\r\n          <path d=\"M39 40L22 14\" stroke=\"#CBD5E1\" stroke-width=\"3.5\" stroke-linecap=\"round\"/>\r\n        </svg>`\r\n      },\r\n      pegamento: {\r\n        id: \"pegamento\", name: \"Pegamento\", bg: \"bg-[#f3e8ff]\", border: \"border-purple-300\",\r\n        sparkleColors: [\"#c084fc\", \"#a855f7\", \"#e9d5ff\", \"#ffffff\"],\r\n        glowColor: \"rgba(168, 85, 247, 0.5)\",\r\n        glowBright: \"rgba(192, 132, 252, 0.9)\",\r\n        svg: `<svg viewBox=\"0 0 64 64\" class=\"w-12 h-12 sm:w-16 sm:h-16\" fill=\"none\">\r\n          <rect x=\"22\" y=\"24\" width=\"20\" height=\"28\" rx=\"3\" fill=\"#A855F7\" stroke=\"#7E22CE\" stroke-width=\"2\"/>\r\n          <rect x=\"25\" y=\"14\" width=\"14\" height=\"10\" rx=\"1.5\" fill=\"#C084FC\"/>\r\n          <rect x=\"26\" y=\"32\" width=\"12\" height=\"12\" fill=\"#FFFFFF\" rx=\"1\"/>\r\n        </svg>`\r\n      },\r\n      lupa: {\r\n        id: \"lupa\", name: \"Lupa\", bg: \"bg-[#fef9c3]\", border: \"border-yellow-300\",\r\n        sparkleColors: [\"#06b6d4\", \"#a855f7\", \"#38bdf8\", \"#f0abfc\", \"#ffffff\"],\r\n        glowColor: \"rgba(6, 182, 212, 0.5)\",\r\n        glowBright: \"rgba(168, 85, 247, 0.9)\",\r\n        svg: `<svg viewBox=\"0 0 64 64\" class=\"w-12 h-12 sm:w-16 sm:h-16\" fill=\"none\">\r\n          <circle cx=\"26\" cy=\"26\" r=\"15\" fill=\"#E0F2FE\" stroke=\"#CA8A04\" stroke-width=\"4\"/>\r\n          <path d=\"M37 37L52 52\" stroke=\"#854D0E\" stroke-width=\"6\" stroke-linecap=\"round\"/>\r\n          <path d=\"M22 18C20 20 18 23 18 26\" stroke=\"#BAE6FD\" stroke-width=\"2\" stroke-linecap=\"round\"/>\r\n        </svg>`\r\n      },\r\n      sacapuntas: {\r\n        id: \"sacapuntas\", name: \"Sacapuntas\", bg: \"bg-[#e0e7ff]\", border: \"border-indigo-300\",\r\n        sparkleColors: [\"#818cf8\", \"#6366f1\", \"#c7d2fe\", \"#ffffff\"],\r\n        glowColor: \"rgba(99, 102, 241, 0.5)\",\r\n        glowBright: \"rgba(129, 140, 248, 0.9)\",\r\n        svg: `<svg viewBox=\"0 0 64 64\" class=\"w-12 h-12 sm:w-16 sm:h-16\" fill=\"none\">\r\n          <rect x=\"18\" y=\"16\" width=\"28\" height=\"32\" rx=\"4\" fill=\"#6366F1\" stroke=\"#4338CA\" stroke-width=\"2.5\"/>\r\n          <circle cx=\"32\" cy=\"32\" r=\"7\" fill=\"#312E81\"/>\r\n        </svg>`\r\n      },\r\n\r\n      // Set 3 (Nivel 5)\r\n      calculadora: {\r\n        id: \"calculadora\", name: \"Calculadora\", bg: \"bg-[#e0f2fe]\", border: \"border-sky-300\",\r\n        sparkleColors: [\"#38bdf8\", \"#0284c7\", \"#34d399\", \"#ffffff\"],\r\n        glowColor: \"rgba(2, 132, 199, 0.5)\",\r\n        glowBright: \"rgba(56, 189, 248, 0.9)\",\r\n        svg: `<svg viewBox=\"0 0 64 64\" class=\"w-12 h-12 sm:w-16 sm:h-16\" fill=\"none\">\r\n          <rect x=\"16\" y=\"10\" width=\"32\" height=\"44\" rx=\"4\" fill=\"#0284C7\" stroke=\"#0369A1\" stroke-width=\"2\"/>\r\n          <rect x=\"21\" y=\"15\" width=\"22\" height=\"10\" rx=\"1.5\" fill=\"#A7F3D0\"/>\r\n          <circle cx=\"24\" cy=\"33\" r=\"2.5\" fill=\"#FFFFFF\"/><circle cx=\"32\" cy=\"33\" r=\"2.5\" fill=\"#FFFFFF\"/><circle cx=\"40\" cy=\"33\" r=\"2.5\" fill=\"#FFFFFF\"/>\r\n          <circle cx=\"24\" cy=\"42\" r=\"2.5\" fill=\"#FFFFFF\"/><circle cx=\"32\" cy=\"42\" r=\"2.5\" fill=\"#FFFFFF\"/><circle cx=\"40\" cy=\"42\" r=\"2.5\" fill=\"#F59E0B\"/>\r\n        </svg>`\r\n      },\r\n      globo: {\r\n        id: \"globo\", name: \"Globo\", bg: \"bg-[#fffaf0]\", border: \"border-amber-300\",\r\n        sparkleColors: [\"#3b82f6\", \"#22c55e\", \"#60a5fa\", \"#86efac\", \"#ffffff\"],\r\n        glowColor: \"rgba(59, 130, 246, 0.5)\",\r\n        glowBright: \"rgba(34, 197, 94, 0.9)\",\r\n        svg: `<svg viewBox=\"0 0 64 64\" class=\"w-12 h-12 sm:w-16 sm:h-16\" fill=\"none\">\r\n          <circle cx=\"32\" cy=\"26\" r=\"16\" fill=\"#38BDF8\" stroke=\"#0284C7\" stroke-width=\"2\"/>\r\n          <path d=\"M22 24C24 20 28 20 31 22C34 24 37 21 40 24\" fill=\"#4ADE80\"/>\r\n          <path d=\"M25 32C28 34 32 30 36 33\" fill=\"#4ADE80\"/>\r\n          <path d=\"M32 42V52\" stroke=\"#92400E\" stroke-width=\"3\" stroke-linecap=\"round\"/>\r\n          <path d=\"M22 54H42\" stroke=\"#92400E\" stroke-width=\"3.5\" stroke-linecap=\"round\"/>\r\n        </svg>`\r\n      },\r\n      pincel: {\r\n        id: \"pincel\", name: \"Pincel\", bg: \"bg-[#f5e8ff]\", border: \"border-purple-300\",\r\n        sparkleColors: [\"#ec4899\", \"#d946ef\", \"#f472b6\", \"#ffffff\"],\r\n        glowColor: \"rgba(236, 72, 153, 0.5)\",\r\n        glowBright: \"rgba(217, 70, 239, 0.9)\",\r\n        svg: `<svg viewBox=\"0 0 64 64\" class=\"w-12 h-12 sm:w-16 sm:h-16\" fill=\"none\">\r\n          <path d=\"M16 48L38 22\" stroke=\"#B45309\" stroke-width=\"4.5\" stroke-linecap=\"round\"/>\r\n          <path d=\"M43 14C45 9 50 10 50 10C50 10 51 15 46 17L41 19L38 16L43 14Z\" fill=\"#EC4899\"/>\r\n        </svg>`\r\n      },\r\n      microscopio: {\r\n        id: \"microscopio\", name: \"Microscopio\", bg: \"bg-[#e6fbf3]\", border: \"border-emerald-300\",\r\n        sparkleColors: [\"#10b981\", \"#059669\", \"#6ee7b7\", \"#ffffff\"],\r\n        glowColor: \"rgba(16, 185, 129, 0.5)\",\r\n        glowBright: \"rgba(5, 150, 105, 0.9)\",\r\n        svg: `<svg viewBox=\"0 0 64 64\" class=\"w-12 h-12 sm:w-16 sm:h-16\" fill=\"none\">\r\n          <rect x=\"28\" y=\"10\" width=\"8\" height=\"20\" rx=\"2\" transform=\"rotate(20 32 20)\" fill=\"#059669\"/>\r\n          <circle cx=\"26\" cy=\"36\" r=\"10\" stroke=\"#047857\" stroke-width=\"3\" fill=\"none\"/>\r\n          <path d=\"M18 52H46\" stroke=\"#065F46\" stroke-width=\"4\" stroke-linecap=\"round\"/>\r\n          <path d=\"M30 46V52\" stroke=\"#065F46\" stroke-width=\"4\"/>\r\n        </svg>`\r\n      }\r\n    };\r\n\r\n    let currentLevel = 1;\r\n    let placedItemKey = null;\r\n    let isLevelCompleted = false;\r\n\r\n    function getLevelItems(lvl) {\r\n      if (lvl <= 3) return [\"lapiz\", \"borrador\", \"cuaderno\", \"regla\"];\r\n      if (lvl === 4) return [\"tijeras\", \"pegamento\", \"lupa\", \"sacapuntas\"];\r\n      return [\"calculadora\", \"globo\", \"pincel\", \"microscopio\"];\r\n    }\r\n\r\n    function initGame() {\r\n      updateLevelUI();\r\n    }\r\n\r\n    function updateLevelUI() {\r\n      const levelData = GAME_LEVELS[currentLevel - 1];\r\n      placedItemKey = null;\r\n      isLevelCompleted = false;\r\n\r\n      // Header\r\n      document.getElementById('level-title-badge').textContent = levelData.title;\r\n      renderDots();\r\n\r\n      const backBtn = document.getElementById('btn-back');\r\n      if (currentLevel > 1) {\r\n        backBtn.classList.remove('hidden');\r\n        backBtn.classList.add('flex');\r\n      } else {\r\n        backBtn.classList.add('hidden');\r\n        backBtn.classList.remove('flex');\r\n      }\r\n\r\n      // Dialog & status\r\n      document.getElementById('dialogue-text').innerHTML = levelData.bubble;\r\n      document.getElementById('status-pill-text').textContent = \"Selecciona un elemento para colocarlo en el pupitre y pulsa comprobar\";\r\n      document.getElementById('btn-next').classList.add('hidden');\r\n\r\n      // Actions reset\r\n      configureButtons(false);\r\n      clearDeskUI();\r\n      renderShelf();\r\n    }\r\n\r\n    function renderDots() {\r\n      const container = document.getElementById('level-dots-container');\r\n      container.innerHTML = '';\r\n      for (let i = 1; i <= 5; i++) {\r\n        const dot = document.createElement('span');\r\n        if (i < currentLevel) {\r\n          dot.className = \"w-3 h-3 rounded-full bg-emerald-500\";\r\n        } else if (i === currentLevel) {\r\n          dot.className = \"w-3.5 h-3.5 rounded-full bg-amber-400 ring-2 ring-amber-200 animate-pulse\";\r\n        } else {\r\n          dot.className = \"w-3 h-3 rounded-full bg-slate-200 border border-slate-300\";\r\n        }\r\n        container.appendChild(dot);\r\n      }\r\n    }\r\n\r\n    function renderShelf() {\r\n      const grid = document.getElementById('items-grid');\r\n      grid.innerHTML = '';\r\n      const items = getLevelItems(currentLevel);\r\n\r\n      items.forEach(key => {\r\n        const item = ITEMS_DB[key];\r\n        const isPlaced = (placedItemKey === key);\r\n\r\n        if (isPlaced) {\r\n          const emptySlot = document.createElement('div');\r\n          emptySlot.className = \"h-[85px] sm:h-[110px] rounded-2xl border-2 border-dashed border-amber-900/30 bg-amber-900/10 flex flex-col items-center justify-center p-2 text-center\";\r\n          emptySlot.innerHTML = `<span class=\"text-sm opacity-60\">📍</span><span class=\"text-[10px] font-fredoka text-amber-900/70\">En pupitre</span>`;\r\n          grid.appendChild(emptySlot);\r\n        } else {\r\n          const card = document.createElement('div');\r\n          card.draggable = true;\r\n          card.className = `shelf-item-card flex flex-col items-center justify-center p-2 sm:p-3 rounded-2xl cursor-pointer border-2 shadow-sm ${item.bg} ${item.border}`;\r\n          card.innerHTML = `${item.svg}<span class=\"mt-1 font-fredoka font-bold text-xs sm:text-sm text-slate-800 pointer-events-none\">${item.name}</span>`;\r\n          \r\n          card.onclick = () => placeItemOnDesk(key);\r\n          card.ondragstart = (e) => e.dataTransfer.setData('text/plain', key);\r\n\r\n          grid.appendChild(card);\r\n        }\r\n      });\r\n    }\r\n\r\n    function spawnDeskSparkles(item) {\r\n      const container = document.getElementById('desk-sparkles-layer');\r\n      if (!container) return;\r\n      container.innerHTML = '';\r\n\r\n      const colors = item.sparkleColors || ['#fbbf24', '#f59e0b', '#ffffff'];\r\n      const totalParticles = 20;\r\n\r\n      for (let i = 0; i < totalParticles; i++) {\r\n        const particle = document.createElement('div');\r\n        particle.className = 'sparkle-particle';\r\n\r\n        const angle = (i / totalParticles) * 2 * Math.PI + (Math.random() * 0.4 - 0.2);\r\n        const distance = 50 + Math.random() * 65;\r\n        const tx = Math.cos(angle) * distance;\r\n        const ty = Math.sin(angle) * distance;\r\n        const rot = (Math.random() - 0.5) * 480;\r\n        const scale = 0.8 + Math.random() * 0.8;\r\n        const color = colors[Math.floor(Math.random() * colors.length)];\r\n        const delay = Math.random() * 0.12;\r\n\r\n        particle.style.setProperty('--tx', `${tx}px`);\r\n        particle.style.setProperty('--ty', `${ty}px`);\r\n        particle.style.setProperty('--rot', `${rot}deg`);\r\n        particle.style.setProperty('--scale', scale);\r\n        particle.style.animationDelay = `${delay}s`;\r\n\r\n        const isStar = Math.random() > 0.4;\r\n        const isEightStar = isStar && (Math.random() > 0.5);\r\n\r\n        if (isEightStar) {\r\n          particle.innerHTML = `\r\n            <svg viewBox=\"0 0 24 24\" width=\"24\" height=\"24\" fill=\"${color}\">\r\n              <path d=\"M12 0L14 9L23 12L14 15L12 24L10 15L1 12L10 9L12 0Z\"/>\r\n              <path d=\"M12 4L13.5 10.5L20 12L13.5 13.5L12 20L10.5 13.5L4 12L10.5 10.5L12 4Z\" fill=\"#ffffff\" opacity=\"0.6\"/>\r\n            </svg>\r\n          `;\r\n        } else if (isStar) {\r\n          particle.innerHTML = `\r\n            <svg viewBox=\"0 0 24 24\" width=\"18\" height=\"18\" fill=\"${color}\">\r\n              <path d=\"M12 1L15 9L23 12L15 15L12 23L9 15L1 12L9 9L12 1Z\"/>\r\n            </svg>\r\n          `;\r\n        } else {\r\n          particle.innerHTML = `\r\n            <div style=\"width: ${Math.floor(Math.random() * 6 + 6)}px; height: ${Math.floor(Math.random() * 6 + 6)}px; background: ${color}; border-radius: 9999px; box-shadow: 0 0 8px ${color};\"></div>\r\n          `;\r\n        }\r\n\r\n        container.appendChild(particle);\r\n      }\r\n\r\n      setTimeout(() => {\r\n        container.innerHTML = '';\r\n      }, 1100);\r\n    }\r\n\r\n    function placeItemOnDesk(key) {\r\n      playPop();\r\n      placedItemKey = key;\r\n      const item = ITEMS_DB[key];\r\n\r\n      const deskContainer = document.getElementById('drop-desk-container');\r\n      deskContainer.classList.remove('state-error-glow', 'state-success-glow', 'desk-drag-active');\r\n\r\n      document.getElementById('slot-placeholder').classList.add('hidden');\r\n      \r\n      const placedWrapper = document.getElementById('placed-card-wrapper');\r\n      placedWrapper.className = `w-28 h-28 sm:w-36 sm:h-36 rounded-2xl p-3 flex flex-col items-center justify-center relative placed-item-halo ${item.bg}`;\r\n      placedWrapper.style.setProperty('--glow-color', item.glowColor || 'rgba(245, 158, 11, 0.5)');\r\n      placedWrapper.style.setProperty('--glow-bright', item.glowBright || 'rgba(251, 191, 36, 0.9)');\r\n      placedWrapper.innerHTML = `${item.svg}<span class=\"mt-1 font-fredoka font-bold text-xs sm:text-sm text-slate-800\">${item.name}</span>`;\r\n\r\n      document.getElementById('desk-placed-item').classList.remove('hidden');\r\n      document.getElementById('return-shelf-action').classList.remove('hidden');\r\n\r\n      spawnDeskSparkles(item);\r\n\r\n      renderShelf();\r\n    }\r\n\r\n    function returnItemToShelf() {\r\n      if (!placedItemKey) return;\r\n      playWhoosh();\r\n      placedItemKey = null;\r\n      clearDeskUI();\r\n      renderShelf();\r\n    }\r\n\r\n    function clearDeskUI() {\r\n      const deskContainer = document.getElementById('drop-desk-container');\r\n      deskContainer.classList.remove('state-error-glow', 'state-success-glow', 'desk-drag-active');\r\n      document.getElementById('slot-placeholder').classList.remove('hidden');\r\n      document.getElementById('desk-placed-item').classList.add('hidden');\r\n      document.getElementById('return-shelf-action').classList.add('hidden');\r\n      const sparklesLayer = document.getElementById('desk-sparkles-layer');\r\n      if (sparklesLayer) sparklesLayer.innerHTML = '';\r\n    }\r\n\r\n    function handleSlotClick() {\r\n      if (placedItemKey) returnItemToShelf();\r\n    }\r\n\r\n    function handleDragOver(e) {\r\n      e.preventDefault();\r\n      document.getElementById('drop-desk-container').classList.add('desk-drag-active');\r\n    }\r\n\r\n    function handleDragLeave(e) {\r\n      e.preventDefault();\r\n      document.getElementById('drop-desk-container').classList.remove('desk-drag-active');\r\n    }\r\n\r\n    function handleDrop(e) {\r\n      e.preventDefault();\r\n      document.getElementById('drop-desk-container').classList.remove('desk-drag-active');\r\n      const key = e.dataTransfer.getData('text/plain');\r\n      if (key && ITEMS_DB[key]) placeItemOnDesk(key);\r\n    }\r\n\r\n    function checkCurrentAnswer() {\r\n      playClick();\r\n      const levelData = GAME_LEVELS[currentLevel - 1];\r\n      const deskContainer = document.getElementById('drop-desk-container');\r\n      const dialogueText = document.getElementById('dialogue-text');\r\n      const dialogueBox = document.getElementById('dialogue-box');\r\n\r\n      if (!placedItemKey) {\r\n        playError();\r\n        dialogueBox.classList.add('animate-wiggle');\r\n        setTimeout(() => dialogueBox.classList.remove('animate-wiggle'), 500);\r\n        dialogueText.innerHTML = \"¡Espera explorador! <span class='sparkle-icon'>🧐</span> Primero selecciona o arrastra un objeto al pupitre.\";\r\n        document.getElementById('status-pill-text').textContent = \"⚠️ Coloca un objeto en el pupitre antes de comprobar\";\r\n        return;\r\n      }\r\n\r\n      if (placedItemKey === levelData.correctKey) {\r\n        // Success\r\n        isLevelCompleted = true;\r\n        deskContainer.classList.remove('state-error-glow');\r\n        deskContainer.classList.add('state-success-glow');\r\n\r\n        dialogueText.innerHTML = `<span class=\"text-emerald-700 font-bold\">${levelData.correctMsg}</span>`;\r\n        document.getElementById('status-pill-text').textContent = \"🎉 ¡Correcto! ¡Excelente deducción!\";\r\n\r\n        if (currentLevel < 5) {\r\n          playSuccess();\r\n          document.getElementById('btn-next').classList.remove('hidden');\r\n        } else {\r\n          // Final Victory Level 5\r\n          playWin();\r\n          document.getElementById('btn-next').classList.add('hidden');\r\n          configureButtons(true);\r\n          document.getElementById('status-pill-text').textContent = \"🏆 ¡Has superado los 5 niveles! Elige una opción para continuar\";\r\n        }\r\n        triggerConfetti();\r\n      } else {\r\n        // Error\r\n        playError();\r\n        deskContainer.classList.remove('state-success-glow');\r\n        deskContainer.classList.add('state-error-glow');\r\n        const chosen = ITEMS_DB[placedItemKey];\r\n        dialogueText.innerHTML = `¡Casi! <span class='sparkle-icon'>🤔</span> Has elegido <strong>${chosen.name}</strong> pero no cumple todas las pistas. ¡Inténtalo de nuevo!`;\r\n        document.getElementById('status-pill-text').textContent = \"Prueba con otro objeto de la repisa\";\r\n      }\r\n    }\r\n\r\n    function configureButtons(isGameOver) {\r\n      const btnReset = document.getElementById('btn-reiniciar-nivel');\r\n      const btnCheck = document.getElementById('btn-check');\r\n      const btnReplay = document.getElementById('btn-replay');\r\n      const btnHome = document.getElementById('btn-home');\r\n\r\n      if (isGameOver) {\r\n        btnReset.classList.add('hidden');\r\n        btnCheck.classList.add('hidden');\r\n        btnReplay.classList.remove('hidden');\r\n        btnReplay.classList.add('flex');\r\n        btnHome.classList.remove('hidden');\r\n        btnHome.classList.add('flex');\r\n      } else {\r\n        btnReset.classList.remove('hidden');\r\n        btnReset.classList.add('flex');\r\n        btnCheck.classList.remove('hidden');\r\n        btnCheck.classList.add('flex');\r\n        btnReplay.classList.add('hidden');\r\n        btnReplay.classList.remove('flex');\r\n        btnHome.classList.add('hidden');\r\n        btnHome.classList.remove('flex');\r\n      }\r\n    }\r\n\r\n    function resetCurrentLevelState() {\r\n      playClick();\r\n      returnItemToShelf();\r\n      const levelData = GAME_LEVELS[currentLevel - 1];\r\n      document.getElementById('dialogue-text').innerHTML = levelData.bubble;\r\n      document.getElementById('btn-next').classList.add('hidden');\r\n      document.getElementById('status-pill-text').textContent = \"Nivel reiniciado. ¡Vuelve a intentarlo!\";\r\n      isLevelCompleted = false;\r\n    }\r\n\r\n    function replayLevelOrGame() {\r\n      playClick();\r\n      configureButtons(false);\r\n      returnItemToShelf();\r\n      const levelData = GAME_LEVELS[currentLevel - 1];\r\n      document.getElementById('dialogue-text').innerHTML = `¡A jugar! <span class=\"sparkle-icon\">🚀</span> ¿Listo explorador?`;\r\n      document.getElementById('status-pill-text').textContent = \"Elige tu objeto favorito para probar\";\r\n      isLevelCompleted = false;\r\n    }\r\n\r\n    function restartGameEntirely() {\n      playClick();\n      if (window.parent && window.parent !== window) {\n        window.parent.postMessage({ type: \"description-match-home\" }, \"*\");\n      }\n    }\r\n\r\n    function goToNextLevel() {\r\n      playClick();\r\n      if (currentLevel < 5) {\r\n        changeLevel(currentLevel + 1);\r\n      }\r\n    }\r\n\r\n    function changeLevel(newLvl) {\r\n      if (newLvl >= 1 && newLvl <= 5) {\r\n        currentLevel = newLvl;\r\n        updateLevelUI();\r\n      }\r\n    }\r\n\r\n    function triggerConfetti() {\r\n      const colors = ['#EF4444', '#10B981', '#3B82F6', '#F59E0B', '#EC4899', '#8B5CF6'];\r\n      for (let i = 0; i < 36; i++) {\r\n        const p = document.createElement('div');\r\n        p.className = 'fixed pointer-events-none z-50 rounded-sm shadow-sm';\r\n        p.style.width = `${Math.random() * 8 + 6}px`;\r\n        p.style.height = `${Math.random() * 12 + 6}px`;\r\n        p.style.backgroundColor = colors[Math.floor(Math.random() * colors.length)];\r\n        p.style.left = '50%';\r\n        p.style.top = '50%';\r\n        p.style.transition = 'all 1.1s cubic-bezier(0.2, 1, 0.3, 1)';\r\n        document.body.appendChild(p);\r\n\r\n        setTimeout(() => {\r\n          const dx = (Math.random() - 0.5) * 550;\r\n          const dy = -Math.random() * 320 - 50;\r\n          p.style.transform = `translate(${dx}px, ${dy}px) rotate(${Math.random() * 720}deg)`;\r\n          p.style.opacity = '0';\r\n        }, 15);\r\n\r\n        setTimeout(() => p.remove(), 1200);\r\n      }\r\n    }\r\n\r\n    window.addEventListener('DOMContentLoaded', initGame);\r\n  </script>\r\n</body></html>";

export default function DescriptionMatchGamePage() {
  const navigate = useNavigate();
  const frameRef = useRef<HTMLIFrameElement>(null);

  useEffect(() => {
    const onMessage = (event: MessageEvent) => {
      if (event.source !== frameRef.current?.contentWindow) return;
      if (event.data?.type === 'description-match-home') {
        navigate('/semana/1');
      }
    };
    window.addEventListener('message', onMessage);
    return () => window.removeEventListener('message', onMessage);
  }, [navigate]);

  return (
    <div className="relative h-screen w-full">
      <KidBackOverlay
        onClick={() => navigate('/semana/1/description-match')}
        label="Volver al inicio del juego"
      />
      <iframe
        ref={frameRef}
        title="Descubre los Objetos"
        srcDoc={gameHtml}
        className="h-screen w-full border-0 bg-[#fef9c3]"
      />
    </div>
  );
}
